/* ═══════════════════════════════════════════════════════════
   SCROLL PANEL — text content driven by scroll progress
   ═══════════════════════════════════════════════════════════ */
function ScrollPanel({ progress, range, side, keepVisible, children }: {
  progress: MotionValue<number>;
  range: [number, number];
  side: 'left' | 'right' | 'center';
  keepVisible?: boolean;
  children: React.ReactNode;
}) {
  const span = range[1] - range[0];
  const S = range[0];

  const opacity = useTransform(progress,
    keepVisible
      ? [S + span * 0.5, S + span * 0.7, S + span * 0.85, range[1]]
      : [S, S + span * 0.12, S + span * 0.22, S + span * 0.68, S + span * 0.85, range[1]],
    keepVisible
      ? [0, 0, 1, 1]
      : [0, 0.6, 1, 1, 0.4, 0],
  );

  const xOff = side === 'left' ? -80 : side === 'right' ? 80 : 0;
  const yOff = side === 'center' ? 50 : 0;

  const x = useTransform(progress,
    [S, S + span * 0.22, S + span * 0.68, range[1]],
    [xOff, 0, 0, -xOff * 0.5],
  );
  const y = useTransform(progress,
    [S, S + span * 0.22, S + span * 0.68, range[1]],
    [yOff, 0, 0, -yOff * 0.5],
  );

  return (
    <motion.div className={`scroll-panel panel-${side}`} style={side === 'center' ? { opacity } : { opacity, x, y }}>
      {children}
    </motion.div>
  );
}

/* ═══════════════════════════════════════════════════════════
   SHOTGUN BLAST — particle system for pellet spread
   ═══════════════════════════════════════════════════════════ */
interface Pellet {
  x: number; y: number;
  vx: number; vy: number;
  r: number; opacity: number;
  life: number; maxLife: number;
}

function ShotgunBlast({ active }: { active: boolean }) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const pelletsRef = useRef<Pellet[]>([]);
  const rafRef = useRef<number>(0);
  const lastSpawnRef = useRef(0);

  const hasFiredRef = useRef(false);

  const spawnBurst = useCallback(() => {
    const pellets: Pellet[] = [];
    // Single burst: 50 pellets in a cone
    const count = 50;
    for (let i = 0; i < count; i++) {
      const angle = (Math.random() - 0.5) * 0.7;
      const speed = 3 + Math.random() * 6;
      pellets.push({
        x: 0, y: 0,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        r: 1.5 + Math.random() * 2.5,
        opacity: 0.7 + Math.random() * 0.3,
        life: 0,
        maxLife: 60 + Math.random() * 50,
      });
    }
    pelletsRef.current.push(...pellets);
  }, []);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const resize = () => {
      canvas.width = canvas.offsetWidth * 2;
      canvas.height = canvas.offsetHeight * 2;
      ctx.scale(2, 2);
    };
    resize();
    window.addEventListener('resize', resize);

    const animate = () => {
      if (!ctx || !canvas) return;
      const w = canvas.offsetWidth;
      const h = canvas.offsetHeight;
      ctx.clearRect(0, 0, w, h);

      // Canvas covers weapon-sticky (full viewport)
      // weapon-container is 55% wide (max 720px), centered via flexbox
      // SVG viewBox 820x300, width=100% of container, height=auto
      // Muzzle at viewBox coords (797, 95)
      const containerW = Math.min(w * 0.55, 720);
      const containerLeft = (w - containerW) / 2;
      const svgH = containerW * (300 / 820);
      const svgTop = (h - svgH) / 2;
      const originX = containerLeft + (797 / 820) * containerW;
      const originY = svgTop + (95 / 300) * svgH;

      // Single shot: fire once when active
      if (active && !hasFiredRef.current) {
        hasFiredRef.current = true;
        lastSpawnRef.current = Date.now();
        spawnBurst();
      }
      // Reset when scrolling back up
      if (!active) {
        hasFiredRef.current = false;
      }

      // Update & draw pellets
      const alive: Pellet[] = [];
      for (const p of pelletsRef.current) {
        p.life++;
        p.x += p.vx;
        p.y += p.vy;
        p.vy += 0.02; // slight gravity
        p.vx *= 0.99; // drag

        const progress = p.life / p.maxLife;
        if (progress >= 1) continue;

        const alpha = p.opacity * (1 - progress * progress);
        const size = p.r * (1 - progress * 0.3);

        // Draw pellet
        ctx.beginPath();
        ctx.arc(originX + p.x, originY + p.y, size, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(0, 255, 65, ${alpha})`;
        ctx.fill();

        // Glow
        ctx.beginPath();
        ctx.arc(originX + p.x, originY + p.y, size * 2.5, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(0, 255, 65, ${alpha * 0.15})`;
        ctx.fill();

        // Trail
        if (progress < 0.5) {
          ctx.beginPath();
          ctx.moveTo(originX + p.x, originY + p.y);
          ctx.lineTo(originX + p.x - p.vx * 3, originY + p.y - p.vy * 3);
          ctx.strokeStyle = `rgba(0, 255, 65, ${alpha * 0.3})`;
          ctx.lineWidth = size * 0.5;
          ctx.stroke();
        }

        alive.push(p);
      }
      pelletsRef.current = alive;

      // Muzzle flash when spawning
      if (active && Date.now() - lastSpawnRef.current < 150) {
        const flashAlpha = 1 - (Date.now() - lastSpawnRef.current) / 150;
        ctx.beginPath();
        ctx.arc(originX, originY, 8, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(0, 255, 65, ${flashAlpha * 0.6})`;
        ctx.fill();
        ctx.beginPath();
        ctx.arc(originX, originY, 20, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(0, 255, 65, ${flashAlpha * 0.15})`;
        ctx.fill();
      }

      rafRef.current = requestAnimationFrame(animate);
    };

    rafRef.current = requestAnimationFrame(animate);
    return () => {
      cancelAnimationFrame(rafRef.current);
      window.removeEventListener('resize', resize);
    };
  }, [active, spawnBurst]);

  return (
    <canvas
      ref={canvasRef}
      style={{
        position: 'absolute',
        top: 0, left: 0,
        width: '100%', height: '100%',
        pointerEvents: 'none',
        zIndex: 10,
        overflow: 'visible',
      }}
    />
  );
}

